# owner: platform
import unittest

from hourglass.models import Span
from hourglass.gaps import find_gaps

class FindGapsTests(unittest.TestCase):
    def test_gap_in_the_middle(self):
        result = find_gaps(
            [Span(540, 720), Span(780, 1020)],
            Span(540, 1020)
        )
        want = ["gap 12:00-13:00 (60 min)"]
        self.assertEqual(result, want)

    def test_gaps_at_both_ends(self):
        result = find_gaps(
            [Span(600, 660)], Span(540, 720)
        )
        self.assertEqual(
            result,
            [
                "gap 09:00-10:00 (60 min)",
                "gap 11:00-12:00 (60 min)"
            ]
        )

    def test_full_coverage_has_no_gaps(self):
        result = find_gaps([Span(0, 100)], Span(0, 100))
        self.assertEqual(result, [])

    def test_nobody_working_is_one_gap(self):
        result = find_gaps([], Span(540, 600))
        want = ["gap 09:00-10:00 (60 min)"]
        self.assertEqual(result, want)

    def test_span_outside_opening_hours_raises(self):
        with self.assertRaises(ValueError):
            find_gaps(
                [Span(500, 600)], Span(540, 1020)
            )
